 "demo-steps": [
  {
   "step": 1,
   "caption": "Two agents join the bus. Each names itself with --as.",
   "command": "agentbus --as lead join --role planner",
   "output": "joined as lead on ~/src/app/.agentbus/bus.db\r\n"
  },
  {
   "step": 2,
   "caption": "",
   "command": "agentbus --as worker join --role implementer --tool codex",
   "output": "joined as worker on ~/src/app/.agentbus/bus.db\r\n"
  },
  {
   "step": 3,
   "caption": "The lead sets the one goal every agent sees first.",
   "command": "agentbus --as lead goal \"Move auth to the new token API\"",
   "output": "goal: Move auth to the new token API\r\n"
  },
  {
   "step": 4,
   "caption": "The lead posts the task to the worker.",
   "command": "agentbus --as lead post \"Move src/auth/ onto the new token API.\" --to worker",
   "output": "posted #1 to worker [note]\r\n"
  },
  {
   "step": 5,
   "caption": "The worker reads its inbox.",
   "command": "agentbus --as worker inbox",
   "output": "#1 lead -> worker [note] · 01:53\r\n  Move src/auth/ onto the new token API.\r\n"
  },
  {
   "step": 6,
   "caption": "The worker claims the folder before it edits.",
   "command": "agentbus --as worker claim src/auth/ --purpose \"token refactor\"",
   "output": "claimed src/auth/ for 2h (until 03:53)\r\n"
  },
  {
   "step": 7,
   "caption": "The lead tries to edit a file inside it. The claim is refused, which is the point.",
   "command": "agentbus --as lead claim src/auth/login.py --purpose \"quick fix\"",
   "output": "agentbus: src/auth/login.py overlaps src/auth/, claimed by worker until 03:53 (purpose: \"token \r\n  refactor\"). Do not edit it yet. Ask worker: agentbus --as lead post QUESTION --to worker --kind \r\n  question, or choose another resource. worker was last seen just now.\r\n"
  },
  {
   "step": 8,
   "caption": "The worker finishes and hands off.",
   "command": "agentbus --as worker post \"Auth is moved and tests pass. Over to you for review.\" --to lead --kind handoff",
   "output": "posted #2 to lead [handoff]\r\n"
  },
  {
   "step": 9,
   "caption": "Any agent can catch up in one call.",
   "command": "agentbus --as lead brief",
   "output": "goal: Move auth to the new token API (set by lead)\r\nhere (2):\r\n  worker (implementer, codex), now, holds src/auth/ [token refactor]\r\n  lead (planner), 7s ago\r\nopen questions: none\r\nunread handoffs and alerts (1):\r\n  #2 worker [handoff]: Auth is moved and tests pass. Over to you for review.\r\npending between others: none\r\nfacts: none\r\nnext: agentbus --as lead inbox\r\n"
  },
  {
   "step": 10,
   "caption": "The worker lets go of the folder.",
   "command": "agentbus --as worker release src/auth/",
   "output": "released src/auth/\r\n"
  },
  {
   "step": 11,
   "caption": "Proposed: the lead takes the folder for review, so the claim changes hands.",
   "command": "agentbus --as lead claim src/auth/ --purpose review",
   "output": "claimed src/auth/ for 2h (until 03:54)\r\n"
  }
 ],
